<?php
namespace ProjectPress\API;
use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\Governance\GovernanceRepository;use ProjectPress\Includes\Project\Governance\GovernanceService;use ProjectPress\Includes\Project\ProjectManager;use WP_Error;use WP_REST_Request;use WP_REST_Response;use WP_REST_Server;
if(!defined('ABSPATH')){exit;}
final class GovernanceRoutes{
 private const TYPES=array('risks'=>'risk','issues'=>'issue','dependencies'=>'dependency','decisions'=>'decision');
 public static function register_routes():void{register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/governance/(?P<type>risks|issues|dependencies|decisions)',array(array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'index'),'permission_callback'=>array(self::class,'can_read')),array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array(self::class,'create'),'permission_callback'=>array(self::class,'can_edit'))));register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/governance/(?P<type>risks|issues|dependencies|decisions)/(?P<id>\d+)',array(array('methods'=>WP_REST_Server::EDITABLE,'callback'=>array(self::class,'update'),'permission_callback'=>array(self::class,'can_edit')),array('methods'=>WP_REST_Server::DELETABLE,'callback'=>array(self::class,'delete'),'permission_callback'=>array(self::class,'can_edit'))));}
 public static function index(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repository($r);return self::success(array_map(static fn($item)=>$item->to_array(),$repo->for_project($project->get_id())));}
 public static function create(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repository($r);$service=self::service($r,$repo);return self::domain($service->create($project->get_id(),self::input($r)),201);}
 public static function update(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repository($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$project->get_id())return self::not_found();return self::domain(self::service($r,$repo)->update($record,self::input($r)));}
 public static function delete(WP_REST_Request$r){$project=self::project($r);if(is_wp_error($project))return$project;$repo=self::repository($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$project->get_id())return self::not_found();$result=self::service($r,$repo)->delete($record);return is_wp_error($result)?$result:self::success(array('deleted'=>(bool)$result,'id'=>$record->get_id()));}
 public static function can_read(WP_REST_Request$r){$project=self::project($r);return is_wp_error($project)?$project:((new ProjectPermissions())->can_view($project)?true:self::forbidden());}public static function can_edit(WP_REST_Request$r){$project=self::project($r);return is_wp_error($project)?$project:((new ProjectPermissions())->can_edit($project)?true:self::forbidden());}
 private static function project(WP_REST_Request$r){$id=sanitize_text_field((string)$r->get_param('project'));$project=ProjectManager::get_instance()->resolve($id);return is_wp_error($project)?new WP_Error('projectpress_rest_project_not_found',__('Project not found.','projectpress'),array('status'=>404)):$project;}
 private static function repository(WP_REST_Request$r):GovernanceRepository{return new GovernanceRepository(self::type($r));}private static function service(WP_REST_Request$r,GovernanceRepository$repo):GovernanceService{return new GovernanceService(self::type($r),$repo,ProjectManager::get_instance()->repository(),new ProjectPermissions());}private static function type(WP_REST_Request$r):string{return self::TYPES[sanitize_key((string)$r['type'])]??'risk';}
 private static function input(WP_REST_Request$r):array{return array('title'=>sanitize_text_field((string)$r->get_param('title')),'description'=>sanitize_textarea_field((string)$r->get_param('description')),'status'=>sanitize_key((string)($r->get_param('status')?:'open')),'probability'=>sanitize_key((string)$r->get_param('probability')),'impact'=>sanitize_key((string)$r->get_param('impact')),'target_type'=>sanitize_key((string)$r->get_param('target_type')),'target_id'=>absint($r->get_param('target_id')));}
 private static function success($data,int$status=200):WP_REST_Response{return new WP_REST_Response(array('success'=>true,'data'=>$data),$status);}private static function domain($result,int$status=200){return is_wp_error($result)?$result:self::success(is_object($result)&&method_exists($result,'to_array')?$result->to_array():$result,$status);}private static function forbidden():WP_Error{return new WP_Error('projectpress_rest_forbidden',__('You do not have permission to perform this action.','projectpress'),array('status'=>rest_authorization_required_code()));}private static function not_found():WP_Error{return new WP_Error('projectpress_governance_not_found',__('Governance record not found.','projectpress'),array('status'=>404));}
}
